import pandas as pd
import numpy as np

# Calculate indicators
def calculate_indicators(data):
    data['MFI'] = data['Close'].rolling(window=14).apply(lambda x: money_flow_index(x))
    data['Stoch_%K'] = data['Close'].rolling(window=14).apply(lambda x: stochastic_k(x))
    data['Stoch_%D'] = data['Stoch_%K'].rolling(window=3).mean()
